import rclpy

# 提供ROS节点的初始化、创建、通信等基础通信
from rclpy.node import Node

# 导入ROS2节点的基类
from face_interfaces.srv import FaceDetector

# 导入自定义的服务接口FaceDetector
from sensor_msgs.msg import Image

# ROS2用于传输图片的包
from ament_index_python.packages import get_package_share_directory

# ROS2用于获取共享目录的包
import cv2

# 用于ROS2和OpenCv格式转换
from cv_bridge import CvBridge


class FaceDetectorClient(Node):
    def __init__(self):
        super().__init__("face_detect_client")
        self.client_ = self.create_client(FaceDetector, "/face_detect")
        self.bridge_ = CvBridge()
        self.test1_image_path_ = (
            get_package_share_directory("demo_python_service") + "/resource/test1.jpg"
        )
        self.test2_image_path_ = (
            get_package_share_directory("demo_python_service") + "/resource/test2.jpg"
        )
        self.image_1_ = cv2.imread(self.test1_image_path_)
        self.image_2_ = cv2.imread(self.test2_image_path_)
        # image_1_和image_2_是OpenCv格式的图片

    def send_request(self):
        # 等待服务是否上线
        while self.client_.wait_for_service(timeout_sec=1.0) is False:
            self.get_logger().info(f"等待服务端上线...")
        # 构造Request
        request_1_ = FaceDetector.Request()
        request_2_ = FaceDetector.Request()
        request_1_.image = self.bridge_.cv2_to_imgmsg(self.image_1_)
        request_2_.image = self.bridge_.cv2_to_imgmsg(self.image_2_)
        # 发送并 spin 等待服务处理完成
        # 现在的future波嗯灭有包含结果，需要等待服务端完成才会把数据放入future中
        future_1_ = self.client_.call_async(request_1_)
        future_2_ = self.client_.call_async(request_2_)

        # 等待服务端相应，等待future中有了数据
        rclpy.spin_until_future_complete(self, future_1_)
        rclpy.spin_until_future_complete(self, future_2_)

        # 根据处理结果
        response_1_ = future_1_.result()
        response_2_ = future_2_.result()
        self.get_logger().info(
            f" 接收到响应 : 图像中共有：{response_1_.number} 张脸，耗时 {response_1_.use_time}"
        )
        self.show_face_locations(response_1_, self.image_1_, "image_1")

        self.get_logger().info(
            f" 接收到响应 : 图像中共有：{response_2_.number} 张脸，耗时 {response_2_.use_time}"
        )
        self.show_face_locations(response_2_, self.image_2_, "image_2")

    def show_face_locations(self, response, image, image_name):
        # 复制图像避免修改原始图像
        display_image=image.copy()
        for i in range(response.number):
            top = response.top[i]
            left = response.left[i]
            right = response.right[i]
            bottom = response.bottom[i]
            cv2.rectangle(display_image, (left, top), (right, bottom), (255, 0, 0), 2)
        cv2.imshow(image_name, display_image)
        cv2.waitKey(1)


def main(args=None):
    rclpy.init(args=None)
    face_detect_client_ = FaceDetectorClient()
    face_detect_client_.send_request()
    rclpy.shutdown()